% STATUS: SCRATCH -- 2026-11-03 (user): does the measurement-frame step follow Delta x_d = s cos(theta-hat_y), Delta z_d = -s sin(theta-hat_y) (s = +-du along u-hat of V-hat[k], u-hat = (cos theta_y, 0, -sin theta_y))? Current flow seed 1 (temp_1103_flow.mat), the scan line closest to the bead centre. Prediction uses theta-hat[k] (previous log row). Residual = actual - prediction, compared with the regulation step along w-hat. Figure in Preview. Output fig_1103_step_split.png
here = fileparts(mfilename('fullpath'));  root = fileparts(fileparts(here));  addpath(here);
fo = fullfile(root, 'test_results', 'temp_3d_wsonly');  load(fullfile(fo, 'temp_1103_flow.mat'), 'r');  du = 40 / 1612;  FS = 14;  cT = [0.85 0 0];  cE = [0 0.25 0.85];  th = char(952);
n = find(isfinite(r.aN(1:r.kend)), 1, 'last') - 1;  t = r.t(1:n);  t = t(:);  D = r.pd(2:n + 1, :) - r.pd(1:n, :);  ty = [NaN; r.thy(1:n - 1)] * pi / 180;  tx = [NaN; r.thx(1:n - 1)] * pi / 180;
p = r.p(1:n, :);  isv = movmean([0; diff(p(:, 2))], 21) > 0.012;  stepv = conv(double(isv), ones(61, 1), 'same') > 0;  id = cumsum(diff([0; stepv]) == 1) + 1;  id(stepv | t < r.tsc + 0.5 | t > r.rs_tend) = 0;
L = unique(id(id > 0));  my = arrayfun(@(l) mean(p(id == l, 2)), L);  [~, j] = min(abs(my));  k = find(id == L(j));  sg = sign(median(D(k, 1) ./ cos(ty(k))));  s = sg * du;
Px = s * cos(ty(k));  Pz = -s * sin(ty(k));  Wh = [sin(ty(k)) .* cos(tx(k)), -sin(tx(k)), cos(ty(k)) .* cos(tx(k))];  dw = sum(D(k, :) .* Wh, 2);  Rx = D(k, 1) - Px;  Rz = D(k, 3) - Pz;
fprintf('line %d (mean y %.2f um), direction %+d, theta-hat_y %.0f..%.0f deg\n', L(j), my(j), sg, min(ty(k)) * 180 / pi, max(ty(k)) * 180 / pi);
fprintf('residual x rms %.2e, z rms %.2e um | regulation step along w-hat rms %.2e um | residual minus regulation part: x rms %.2e, z rms %.2e um | step length median %.5f um\n', rms(Rx), rms(Rz), rms(dw), rms(Rx - dw .* Wh(:, 1)), rms(Rz - dw .* Wh(:, 3)), median(vecnorm(D(k, :), 2, 2)));
g = figure('Color', 'w', 'Position', [40 40 1700 900], 'Visible', 'off');  tl = tiledlayout(3, 1, 'TileSpacing', 'compact', 'Padding', 'compact');  tk = t(k);
a1 = nexttile(tl);  hold(a1, 'on');  plot(a1, tk, ty(k) * 180 / pi, 'Color', cE, 'LineWidth', 1.2);  ylabel(a1, [th char(770) '_y  [deg]']);  yline(a1, 90, 'k:');  yline(a1, -90, 'k:');
a2 = nexttile(tl);  hold(a2, 'on');  h1 = plot(a2, tk, Px, 'Color', cT, 'LineWidth', 2.2);  h2 = plot(a2, tk, D(k, 1), 'Color', cE, 'LineWidth', 1);  ylabel(a2, '\Delta x_d  [\mum per step]');  legend(a2, [h1 h2], {'s cos\theta_y', 'actual'}, 'Location', 'northeast');
a3 = nexttile(tl);  hold(a3, 'on');  h3 = plot(a3, tk, Pz, 'Color', cT, 'LineWidth', 2.2);  h4 = plot(a3, tk, D(k, 3), 'Color', cE, 'LineWidth', 1);  ylabel(a3, '\Delta z_d  [\mum per step]');  xlabel(a3, 'Time (sec)');  legend(a3, [h3 h4], {'-s sin\theta_y', 'actual'}, 'Location', 'northeast');
for a = [a1 a2 a3]; xlim(a, [tk(1) tk(end)]);  box(a, 'on');  set(a, 'FontSize', FS, 'FontWeight', 'bold', 'LineWidth', 1.2); end;  ylim(a2, [-0.03 0.03]);  ylim(a3, [-0.03 0.03]);
fn = fullfile(fo, 'fig_1103_step_split.png');  exportgraphics(g, fn, 'Resolution', 130);  close(g);  system(['open -a Preview "' fn '"']);
